    residuals[i] = val - lim_val;
    if (i == 0) residual->x = residuals[i];
    else if (i == 1) residual->y = residuals[i];
    else residual->z = residuals[i];

    if (val < limits[i].min_value || val > limits[i].max_value) {
        sat_mask |= (uint32_t)(1U << i);
    }
}

*mask = sat_mask;

double r_dot = adcs_vec3_dot(residual, residual);
*residual_norm = sqrt(r_dot);

return ADCS_OK;
